create or replace function public.create_withdrawal_request_atomic(p_user_id uuid,p_amount numeric,p_external_id text,p_provider text,p_clabe text,p_beneficiary text,p_metadata jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_existing public.withdraw_requests%rowtype; v_wallet jsonb; v_id uuid; begin if p_user_id is null then raise exception 'USER_REQUIRED'; end if; if coalesce(p_amount,0)<=0 then raise exception 'INVALID_AMOUNT'; end if; if nullif(trim(p_external_id),'') is null then raise exception 'EXTERNAL_ID_REQUIRED'; end if; if trim(coalesce(p_clabe,''))!~'^[0-9]{18}$' then raise exception 'INVALID_CLABE'; end if; if length(trim(coalesce(p_beneficiary,'')))<3 then raise exception 'INVALID_BENEFICIARY'; end if; perform pg_advisory_xact_lock(hashtextextended('withdraw_request:'||trim(p_external_id),0)); select * into v_existing from public.withdraw_requests where external_id=trim(p_external_id) limit 1; if found then if v_existing.user_id<>p_user_id or abs(v_existing.amount-p_amount)>0.01 then raise exception 'WITHDRAW_REQUEST_CONFLICT'; end if; return jsonb_build_object('ok',true,'idempotent',true,'withdrawal_id',v_existing.id,'external_id',v_existing.external_id,'status',v_existing.status,'amount',v_existing.amount,'provider',v_existing.provider); end if; v_wallet:=public.wallet_apply_delta(p_user_id=>p_user_id,p_delta_balance=>-round(p_amount,2),p_delta_bonus=>0,p_delta_locked=>round(p_amount,2),p_reason=>'withdraw_request',p_ref_id=>trim(p_external_id),p_method=>'spei',p_metadata=>jsonb_build_object('provider',lower(coalesce(nullif(trim(p_provider),''),'manual')),'clabe_last4',right(trim(p_clabe),4))||coalesce(p_metadata,'{}'::jsonb)); if coalesce(v_wallet->>'ok','false')<>'true' then raise exception 'WITHDRAW_WALLET_LOCK_FAILED'; end if; insert into public.withdraw_requests(user_id,amount,currency,method,destination,status,metadata,provider,external_id,clabe,beneficiary,provider_payload) values(p_user_id,round(p_amount,2),'MXN','spei',trim(p_clabe),'pending',coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('beneficiary',trim(p_beneficiary),'external_id',trim(p_external_id),'provider',lower(coalesce(nullif(trim(p_provider),''),'manual')),'wallet_tx_id',v_wallet->>'tx_id'),lower(coalesce(nullif(trim(p_provider),''),'manual')),trim(p_external_id),trim(p_clabe),trim(p_beneficiary),'{}'::jsonb) returning id into v_id; return jsonb_build_object('ok',true,'idempotent',false,'withdrawal_id',v_id,'external_id',trim(p_external_id),'status','pending','amount',round(p_amount,2),'provider',lower(coalesce(nullif(trim(p_provider),''),'manual')),'wallet',v_wallet); end; $$;
revoke all on function public.create_withdrawal_request_atomic(uuid,numeric,text,text,text,text,jsonb) from public,anon,authenticated;
grant execute on function public.create_withdrawal_request_atomic(uuid,numeric,text,text,text,text,jsonb) to service_role;
